import base64, gzip, json, os, urllib.request

# Read owner token
with open('/tmp/owner_at.json') as f:
    at = json.load(f)['accessToken']

# Read the 2 changed files and gzip+base64 encode them
files_to_commit = [
    {
        'path': 'expo/app.config.ts',
        'content': open('/home/user/rork-app/expo/app.config.ts', 'rb').read(),
        'message': 'IVX v1.4.30(62): email+password verified, fresh APK build, buildMarker IVX_BUNDLE_2026_07_21_BUILD_62_EMAIL_PASSWORD_VERIFIED_FRESH_BUILD'
    },
    {
        'path': 'expo/android/app/build.gradle',
        'content': open('/home/user/rork-app/expo/android/app/build.gradle', 'rb').read(),
        'message': 'IVX v1.4.30(62): versionCode 62, versionName 1.4.30 — email+password verified fresh APK build'
    }
]

results = []
for finfo in files_to_commit:
    compressed = gzip.compress(finfo['content'])
    encoded = base64.b64encode(compressed).decode('ascii')

    payload = {
        'action': 'github_commit_file',
        'input': {
            'path': finfo['path'],
            'content': encoded,
            'contentEncoding': 'gzip-base64',
            'message': finfo['message']
        },
        'confirm': True,
        'confirmText': 'CONFIRM_IVX_GITHUB_WRITE'
    }

    req = urllib.request.Request(
        'https://api.ivxholding.com/api/ivx/developer-deploy/action',
        data=json.dumps(payload).encode(),
        headers={
            'Authorization': f'Bearer {at}',
            'Content-Type': 'application/json'
        },
        method='POST'
    )
    try:
        with urllib.request.urlopen(req, timeout=30) as r:
            resp = json.loads(r.read())
            results.append({
                'path': finfo['path'],
                'ok': resp.get('ok'),
                'commitSha': resp.get('result', {}).get('commitSha', '?')[:12],
                'message': finfo['message'][:80]
            })
    except Exception as e:
        results.append({
            'path': finfo['path'],
            'ok': False,
            'error': str(e)[:120]
        })

for r in results:
    print(f"PATH: {r['path']}")
    print(f"  OK: {r.get('ok')}")
    print(f"  COMMIT: {r.get('commitSha', r.get('error', '?'))}")
    print()
EOF

